import {transport,config,clearPractice,SupabaseTransport,LocalTransport} from './lib/api.js';
import {BENCHMARKS,pct,goalProbability} from './lib/math.js';
import {outcomeLabel,outcomeDetail} from './lib/visual.js';
import {streams,rankings,teams,teamLead,record} from './lib/stats.js';
import type {Stream} from './lib/stats.js';
import type {Transport,Snapshot,Statistics,Side,MatchView,Observation} from './lib/types.js';
const $=<T extends Element=HTMLElement>(s:string)=>document.querySelector<T>(s);
const esc=(s:unknown)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const icon=(name:string)=>{const paths:Record<string,string>={arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',mute:'<path d="m11 5-6 4H2v6h3l6 4V5zm5 4 6 6m0-6-6 6"/>',sound:'<path d="m11 5-6 4H2v6h3l6 4V5zm5 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]??paths.arrow}</svg>`;};
const getStore=(k:string)=>{try{return localStorage.getItem(k);}catch{return null;}};
const putStore=(k:string,v:string)=>{try{localStorage.setItem(k,v);}catch{}};
let mode=config.mode??'practice';
const hashParams=()=>new URLSearchParams(location.hash.split('?')[1]??'');
let code=hashParams().get('room')?.toUpperCase()??getStore(`penalty:room:${mode}`)??config.defaultRoom??(mode==='local'?'LOCAL':'CLASS');
let api:Transport=transport(mode,code),snapshot:Snapshot|null=null,data:Statistics|null=null,pitch:Pitch|null=null,hostApi:Transport|null=null;
let view=location.hash.slice(1).split('?')[0]||'play',preference:Side|null=null,joined=false,loading=false,submitting=false,preparing=false;
const effects=new Effects();
let opponentFilter='all',error='',offset=0,lastRender='',busyRefresh=false,refreshAgain=false,unsubscribe:(()=>void)|null=null,hostData:Statistics|null=null;
const revealStarts=new Map<string,number>(),seenSent=new Set<string>(),briefingSeen=new Map<string,number>();let revealTimer=0,hostRefreshing=false,lastStatsAt=0,notificationTimer=0,lastHeartbeat=0;
let hostPreflight:Record<string,unknown>|null=null,connection='connecting';
let captchaWidget:string|undefined;
const root=$('#app')!;
function announce(text:string){const el=$('#announcer');if(el)el.textContent=text;}
function toast(text:string){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),4500);}
function fail(e:unknown){if(captchaWidget){window.PENALTY_CAPTCHA='';window.turnstile?.reset(captchaWidget);}error=e instanceof Error?e.message:String(e);const el=$('#error');if(el)el.textContent=error;else toast(error);announce(error);}
function go(next:string){location.hash=next+(code&&mode!=='practice'?`?room=${encodeURIComponent(code)}`:'');}
function badge(side:string){return `<span class="pill ${esc(side)}">${side==='micro'?'↙ Micro':'Macro ↘'}</span>`;}
const isLive=(m:MatchView|null|undefined)=>!!m&&['briefing','locked'].includes(m.status);
function modeNote(){return `<div class="mode-banner"><span>${mode==='practice'?'<strong>SIMULATED PRACTICE</strong> · One simulated partner. Separate from classroom data.':mode==='local'?'<strong>LOCAL TWO-HUMAN REHEARSAL</strong> · Not a deployed classroom room.':'<strong>CLASSROOM ROOM</strong> · Only resolved human decisions enter the game statistics.'}</span><span>Micro is always left. Macro is always right.</span></div>`;}
function shell(body:string){
 if(captchaWidget){window.turnstile?.remove?.(captchaWidget);captchaWidget=undefined;window.PENALTY_CAPTCHA='';}
 pitch?.destroy();pitch=null;clearTimeout(revealTimer);
 root.innerHTML=`<header class="site-header"><a class="brand" href="#play" aria-label="The Penalty Lab home"><span class="brand-mark">↔</span><span class="brand-word">THE PENALTY LAB<small>EC487 · LONDON SCHOOL OF ECONOMICS</small></span></a><nav class="navigation" aria-label="Main navigation">${[['play','Play'],['statistics','Statistics'],['notes','Game theory']].map(([id,label])=>`<button class="nav-link" data-nav="${id}" ${view===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="header-end"><span class="room-tag"><i class="status-dot" id="connection-dot"></i><span id="connection-state" data-state="${connection}">${mode==='practice'?'PRACTICE':esc(code)}</span></span><button class="sound" id="sound-toggle" title="Crowd, kick and countdown sound" aria-label="${effects.sound?'Mute sound':'Enable sound'}" aria-pressed="${effects.sound}">${icon(effects.sound?'sound':'mute')}<span class="sound-label">${effects.sound?'On':'Off'}</span></button><button class="haptics-toggle" id="haptics-toggle" title="${effects.supportsHaptics?'Toggle vibration':'Vibration unavailable in this browser'}" aria-label="${effects.haptics?'Disable':'Enable'} vibration" aria-pressed="${effects.haptics&&effects.supportsHaptics}" ${effects.supportsHaptics?'':'disabled'}>↯</button></div></header><main id="main" tabindex="-1">${view!=='play'&&joined&&isLive(snapshot?.match)?`<div class="notice warning flex between wrap" style="margin-bottom:20px"><span>${snapshot?.match?.status==='briefing'?'Your pre-kick reminder is ready.':'Your penalty is live · <strong id="away-clock">12</strong>s left.'}</span><button id="return-live" class="btn small">Return to Play →</button></div>`:''}<div id="error" class="error-box top-error" role="alert">${esc(error)}</div>${body}${modeNote()}</main><footer class="site-footer"><span>Two sides. Twelve penalties. Put your strategy into play.<br>Ungraded · EC487 classroom game.</span><button id="host-link">Instructor’s room ↗</button></footer>`;
 $('#return-live')?.addEventListener('click',()=>go('play'));root.querySelectorAll<HTMLButtonElement>('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav!));$('#host-link')!.addEventListener('click',()=>go('host'));
 $('#sound-toggle')!.addEventListener('click',()=>{void effects.setSound(!effects.sound);updateEffectControls();});
 $('#haptics-toggle')?.addEventListener('click',()=>{effects.setHaptics(!effects.haptics);updateEffectControls();});
 root.querySelectorAll<HTMLButtonElement>('[data-history]').forEach(b=>b.onclick=()=>{const target=$('#history-detail');if(target)target.textContent=b.dataset.history!;announce(b.dataset.history!);});
}
function mountPitch(state:Parameters<Pitch['set']>[0]){const canvas=$<HTMLCanvasElement>('#pitch');if(canvas)pitch=new Pitch(canvas,state);}
function updateEffectControls(){const b=$('#sound-toggle');if(b){b.innerHTML=icon(effects.sound?'sound':'mute')+`<span class="sound-label">${effects.sound?'On':'Off'}</span>`;b.setAttribute('aria-pressed',String(effects.sound));b.setAttribute('aria-label',effects.sound?'Mute sound':'Enable sound');}$('#haptics-toggle')?.setAttribute('aria-pressed',String(effects.haptics&&effects.supportsHaptics));const check=$<HTMLInputElement>('#join-sound');if(check)check.checked=effects.sound;}
function revealing(m:MatchView){return !!m.result&&snapshot?.me?.feedbackSince===null&&Date.now()-(revealStarts.get(m.id)??Date.now())<CONFIG.reveal_ms;}
function render(force=false){
 if(mode==='supabase'&&(!config.supabaseUrl||!config.supabaseKey)){shell('<section class="page-head"><div class="eyebrow">Deployment setup</div><h1>Connect your classroom.</h1><p>This live build needs its Supabase project URL and publishable key. Add the GitHub variables described in START-HERE.md, then rerun the Pages workflow. No simulated opponents will be introduced into a live room.</p></section>');return;}
 const m=snapshot?.match,me=snapshot?.me;
 if(m?.result&&!revealStarts.has(m.id))revealStarts.set(m.id,me?.feedbackSince!==null?0:Date.now());
 const phase=m?.result?(revealing(m)?'reveal':'feedback'):me?.status??'onboard';
 const signature=JSON.stringify([view,joined,loading,mode,snapshot?.room.phase,snapshot?.room.entryOpen,snapshot?.room.showBenchmarks,!m?snapshot?.waiting:0,me?.status,me?.kicks,me?.keeps,me?.feedbackSince,m?.id,m?.status,m?.ownChoice,m?.kickerPrepared,m?.keeperPrepared,m?.kickerReady,m?.keeperReady,phase,submitting,preparing,opponentFilter,data?.room.version,hostData?.room.version,hostPreflight,error]);
 if(!force&&signature===lastRender)return;lastRender=signature;
 if(view==='host'){renderHost();return;}
 if(loading&&!snapshot){shell('<div class="load-screen"><div class="orbit"></div><p>Recovering your place on the pitch…</p></div>');return;}
 if(view==='statistics'){renderStatistics();return;}if(view==='notes'){renderNotes();return;}if(!joined||!snapshot){renderJoin();return;}
 if(m?.result&&phase==='feedback'){renderFeedback(m);return;}
 if(me?.status==='finished'||(snapshot.room.phase==='ended'&&!me?.pendingResult)){renderFinal();return;}
 renderPlay();
}
function mountCaptcha(){
 if(mode!=='supabase'||!config.turnstileSiteKey)return;
 const target=$<HTMLElement>('#captcha');if(!target)return;
 const load=()=>{if(!target.isConnected||!window.turnstile)return;window.PENALTY_CAPTCHA='';captchaWidget=window.turnstile.render(target,{sitekey:config.turnstileSiteKey,theme:'dark',callback:(token:string)=>{window.PENALTY_CAPTCHA=token;},'expired-callback':()=>{window.PENALTY_CAPTCHA='';},'error-callback':()=>{window.PENALTY_CAPTCHA='';}});};
 if(window.turnstile){load();return;}
 let script=$<HTMLScriptElement>('#turnstile-script');if(!script){script=document.createElement('script');script.id='turnstile-script';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;document.head.append(script);}script.addEventListener('load',load,{once:true});
}
function renderJoin(){
 shell(`<section class="welcome-layout"><div class="welcome-story"><div class="eyebrow">Micro vs Macro · The EC487 penalty game</div><h1>Two sides.<br>One goal.<br><em>Keep them guessing.</em></h1><p>Choose your side of economics. Step up to the spot. Can the class put mixed strategies into play?</p><div class="hero-bits"><div class="hero-bit"><b>12</b><span>penalties to play</span></div><div class="hero-bit"><b>6 + 6</b><span>strike &amp; keep</span></div><div class="hero-bit"><b>12s</b><span>to choose privately</span></div></div><div class="welcome-pitch"><canvas id="pitch" aria-label="Floodlit stadium. Micro is the left side of the goal; Macro is the right side."></canvas><div class="art-bottom"><span>A probability reminder before every penalty.</span><span>← MICRO &nbsp; MACRO →</span></div></div></div><form class="join-form join-panel" id="join-form"><div><div class="eyebrow">Take your place</div><h2>Your side of the game.</h2></div><label>Your classroom username<input name="username" id="username" minlength="2" maxlength="18" autocomplete="nickname" placeholder="e.g. Corner Solution" required><span class="caption">An alias for the ranking, not your real name. 2–18 characters.</span></label><fieldset class="team-fieldset"><legend>Are you naturally a microeconomist or a macroeconomist?</legend><div class="team-choices"><button class="team-choice" type="button" data-side="micro" aria-pressed="${preference==='micro'}"><b>↙ Micro</b><small>My natural side is left.</small></button><button class="team-choice" type="button" data-side="macro" aria-pressed="${preference==='macro'}"><b>Macro ↘</b><small>My natural side is right.</small></button></div></fieldset>${mode!=='practice'?`<label>Classroom room code<input id="room-code" value="${esc(code)}" minlength="4" maxlength="8" autocapitalize="characters" autocomplete="off" required></label>`:''}<label class="sound-opt-in"><input id="join-sound" type="checkbox" ${effects.sound?'checked':''}><span>Enable stadium cheers &amp; countdown ticks<small>Optional. The speaker button mutes all sounds.</small></span></label><div id="captcha"></div><button type="submit" id="join-button" class="btn teal wide">${mode==='practice'?'Step onto the pitch':'Join the classroom'} ${icon('arrow')}</button><p class="privacy-copy">This game is <strong>ungraded</strong>. Your username, team, released choices and scores are shared within your room. Your preference stays fixed. No student email or real name is requested.</p><div class="join-mode"><i class="status-dot"></i>${mode==='practice'?'You are entering isolated, simulated practice.':'Two human players. Private choices. One shared outcome.'}</div></form></section>`);
 $('#join-sound')?.addEventListener('change',e=>{void effects.setSound((e.target as HTMLInputElement).checked);updateEffectControls();});
 mountPitch({hero:true});root.querySelectorAll<HTMLButtonElement>('[data-side]').forEach(b=>b.onclick=()=>{preference=b.dataset.side as Side;root.querySelectorAll('[data-side]').forEach(c=>c.setAttribute('aria-pressed',String((c as HTMLElement).dataset.side===preference)));});mountCaptcha();
 $('#join-form')!.addEventListener('submit',async event=>{event.preventDefault();void effects.unlock();if(!preference){fail(new Error('Choose Micro or Macro before joining.'));return;}const name=$<HTMLInputElement>('#username')!.value,room=$<HTMLInputElement>('#room-code')?.value.toUpperCase().trim();const b=$<HTMLButtonElement>('#join-button')!;b.disabled=true;b.textContent='Taking your place…';error='';try{if(room&&room!==code){code=room;api.close();api=transport(mode,code);}snapshot=await api.join(name,preference);offset=snapshot.serverNow-Date.now();joined=true;putStore(`penalty:joined:${mode}:${code}`,'yes');putStore(`penalty:room:${mode}`,code);subscribe();await refresh();render(true);announce('You have joined the room.');window.scrollTo({top:0});}catch(e){fail(e);window.PENALTY_CAPTCHA='';if(captchaWidget)window.turnstile?.reset(captchaWidget);b.disabled=false;b.textContent='Try joining again';}});
}
function history(){
 const me=snapshot?.me;if(!me)return '';const current=snapshot?.match;
 const penalties=(snapshot?.history??data?.matches??[]).filter(m=>m.status==='resolved'&&m.result&&(m.kicker===me.id||m.keeper===me.id)&&!(current?.id===m.id&&revealing(current))).sort((a,b)=>a.serial-b.serial);
 return `<section class="history-panel" aria-label="Your past penalties"><div class="history-heading"><b>Your penalties</b><span>${penalties.length} / 12</span><span class="history-key"><i class="shape-circle"></i> Striker <i class="shape-square"></i> Goalkeeper</span></div><div class="penalty-history">${Array.from({length:12},(_,i)=>{const m=penalties[i];if(!m)return `<span class="history-empty" aria-label="Penalty ${i+1} not yet completed">${String(i+1).padStart(2,'0')}</span>`;const k=m.kicker===me.id,r=m.result!,win=k?r.goal:!r.goal,opponent=k?m.keeperPlayer:m.kickerPlayer,desc=`Penalty ${i+1} vs ${opponent.username}: ${k?'striker':'goalkeeper'}. ${outcomeDetail(r)}. ${win?'You win':'You lose'}. Striker chose ${r.kickerN?'natural':'unnatural'} (${r.kickerChoice}); goalkeeper chose ${r.keeperChoice}.`;return `<button type="button" class="history-token ${k?'striker':'goalkeeper'} ${win?'success':'failure'}" data-history="${esc(desc)}" title="${esc(desc)}" aria-label="${esc(desc)}"><b>${r.kickerN?'N':'U'}</b><small>${win?'✓':'×'}</small></button>`;}).join('')}</div><p id="history-detail" class="history-detail" aria-live="polite">N / U = the striker’s natural / unnatural choice. Green ✓ = your win; red × = your loss. Tap a penalty for details.</p></section>`;
}
function progressHeader(title='Your next move.'){
 const me=snapshot!.me!,n=me.kicks+me.keeps,m=snapshot!.match,number=m?.result?n:Math.min(12,n+1);
 return `<div class="game-header"><div><div class="eyebrow">${esc(me.username)} · Team ${me.preference} · ${snapshot!.room.phase==='paused'?'Matching paused':'The penalty lab'}</div><h1>${title}</h1></div><div class="personal-progress"><div><b>Penalty ${number}<span class="muted">/12</span></b><p>Strike ${me.kicks}/6 · Keep ${me.keeps}/6</p></div></div></div>${history()}`;
}
function sidePanel(){return `<aside class="side-panel"><div class="side-card rules"><div class="overline">The playbook</div><div class="rule-line"><b>01</b><span>Review the four scoring probabilities. Both players get the same reminder.</span></div><div class="rule-line"><b>02</b><span>Choose privately in twelve seconds. Your first choice is locked.</span></div><div class="rule-line"><b>03</b><span>The server draws the outcome. There is no aiming or timing bonus.</span></div></div><div class="side-card"><div class="overline">Natural for whom?</div><h3>N is always the striker’s natural side.</h3><p class="caption" style="margin-top:12px">Your own Micro or Macro preference defines your team. As goalkeeper, the striker’s preference—not yours—defines N.</p></div><div class="side-card quiet-card"><span class="eyebrow">The question for the class</span><p>Are statistical frequencies distinct from predicted play?</p><button class="text-button" id="side-stats">Explore the statistics →</button></div></aside>`;}
function probabilityFlash(m:MatchView,isKicker:boolean){
 const pref=m.kickerPlayer.preference;
 return `<div class="probability-projection" aria-label="Pre-kick scoring probability flashcard"><div class="flash-heading"><span>BEFORE THE KICK</span><strong>${isKicker?'Your':'The striker’s'} natural side is <span class="${pref}-text">${pref.toUpperCase()}</span>.</strong><small>Four probabilities that the <b>striker scores</b>.</small></div><div class="projected-goal"><table class="probability-table"><thead><tr><th scope="col">Keeper<br>dives</th>${(['micro','macro'] as Side[]).map(side=>`<th scope="col" class="${side}-text">${side==='micro'?'← MICRO':'MACRO →'}<small>Striker’s ${side===pref?'natural (N)':'unnatural (U)'}</small></th>`).join('')}</tr></thead><tbody>${(['micro','macro'] as Side[]).map(keeper=>`<tr><th scope="row" class="${keeper}-text">${keeper==='micro'?'← Micro':'Macro →'}</th>${(['micro','macro'] as Side[]).map(kick=>`<td data-probability="${kick}-${keeper}" class="${kick}-text"><b>${pct(goalProbability(kick,keeper,pref),2)}</b></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="flash-foot">Columns = shot direction. Rows = goalkeeper direction.</p></div>`;
}
function renderPlay(){
 const s=snapshot!,me=s.me!,m=s.match,active=m&&m.status!=='cancelled',isKicker=m?.kicker===me.id,role=isKicker?'striker':'goalkeeper';let body='';
 if(active){
  const own=m.ownChoice,otherReady=isKicker?m.keeperReady:m.kickerReady,brief=m.status==='briefing',prepared=isKicker?m.kickerPrepared:m.keeperPrepared;
  if(brief&&!briefingSeen.has(m.id))briefingSeen.set(m.id,Date.now());
  body=`<div class="arena ${brief?'briefing-arena':''}"><div class="scoreboard"><div class="player-id"><span>STRIKER ${isKicker?'· YOU':''}</span><b>${esc(m.kickerPlayer.username)}</b>${badge(m.kickerPlayer.preference)}</div><div class="clock" id="clock" aria-label="${brief?'Pre-kick reminder. The decision clock has not started.':'Seconds left to choose'}"><svg viewBox="0 0 58 58"><circle class="clock-track" cx="29" cy="29" r="26"/><circle class="clock-fill" id="clock-arc" cx="29" cy="29" r="26"/></svg><b id="seconds">${brief?'↔':'12'}</b></div><div class="player-id right"><span>GOALKEEPER ${!isKicker?'· YOU':''}</span><b>${esc(m.keeperPlayer.username)}</b>${badge(m.keeperPlayer.preference)}</div></div><div class="arena-pitch"><canvas id="pitch" aria-label="The shared pitch. Micro left. Macro right."></canvas>${brief?probabilityFlash(m,!!isKicker):`<span class="natural-tag">STRIKER’S NATURAL SIDE: <strong>${m.kickerPlayer.preference.toUpperCase()}</strong></span>`}</div><div class="action-zone">${brief?`<div class="action-zone-head"><b>You’re the ${role}.</b><span>Decision clock not started</span></div><button class="btn teal wide" id="prepare" ${prepared||preparing?'disabled':''}><span id="prepare-copy">${prepared?'Ready · waiting for the other player…':'Read the probabilities…'}</span>${icon('arrow')}</button><p class="action-note">The reminder disappears when both players are ready. Then you have 12 seconds to choose.</p>`:`<div class="action-zone-head"><b>${m.result?'Both directions released':own?'Your choice is locked':`You’re the ${role}. Choose a side.`}</b><span>${m.result?'One shared outcome':otherReady?'Opponent ready ✓':'Opponent choosing privately'}</span></div>${m.result?`<div class="locked-banner">${m.result.kickerChoice==='micro'?'←':'→'} ${m.result.kickerChoice.toUpperCase()} shot <span class="muted">/</span> ${m.result.keeperChoice==='micro'?'←':'→'} ${m.result.keeperChoice.toUpperCase()} dive</div>`:own?`<div class="locked-banner">${icon('lock')} Locked: <strong>${own.toUpperCase()}</strong><span class="muted">Waiting for the reveal…</span></div>`:`<div class="actions"><button class="choice micro" data-choice="micro" ${submitting?'disabled':''}><span>← Micro</span><span class="keycap" aria-hidden="true">1</span></button><button class="choice macro" data-choice="macro" ${submitting?'disabled':''}><span class="keycap" aria-hidden="true">2</span><span>Macro →</span></button></div>`}<p class="action-note">${m.result?'The ball follows the striker’s choice. The dive follows the goalkeeper’s.':'Use the buttons or ← / → keys. The same camera orientation for both players.'}</p>`}</div></div>`;
 }else{
  const paused=s.room.phase==='paused',lobby=s.room.phase==='lobby',away=me.status==='away';
  body=`<div class="arena"><div class="arena-pitch"><canvas id="pitch" aria-label="Waiting beside a floodlit pitch."></canvas><div class="waiting-overlay"><div class="orbit" aria-hidden="true"></div><h2>${lobby?'The class is gathering.':paused?'A moment on the touchline.':away?'Ready when you are.':'Finding your next opponent…'}</h2><p>${lobby?'Your instructor will start the game.':paused?'Your place is safe. The instructor will resume matching.':away?'The last attempt timed out. No penalty was counted.':'A new matchup. A fresh choice. Your next penalty starts with a probability reminder.'}</p>${away?'<div class="spacer"></div><button class="btn small" id="return-ready">I’m back · find a match</button>':''}</div></div><div class="queue-foot"><span>${badge(me.preference)} <span style="margin-left:7px">${esc(me.username)}</span></span><span><i class="status-dot"></i>${s.waiting} ${s.waiting===1?'player':'players'} waiting</span></div></div>`;
 }
 shell(`${progressHeader(m?.status==='briefing'?'Know your chances.':m?.result?'Watch the play.':'Your next move.')}${active?`<div class="matchup-line"><span class="live-pill">${mode==='practice'?'PRACTICE':'HUMAN MATCH'}</span><span>You vs <strong id="opponent-username">${esc(isKicker?m.keeperPlayer.username:m.kickerPlayer.username)}</strong></span><span>Private choices · same pitch</span></div>`:''}<div class="arena-layout">${body}${sidePanel()}</div>`);
 mountPitch({match:m,revealAt:m?.result?revealStarts.get(m.id):undefined,win:m?.result?(isKicker?m.result.goal:!m.result.goal):undefined});
 root.querySelectorAll<HTMLButtonElement>('[data-choice]').forEach(b=>b.onclick=()=>void choose(b.dataset.choice as Side));$('#side-stats')?.addEventListener('click',()=>go('statistics'));
 $('#prepare')?.addEventListener('click',()=>void prepare());$('#return-ready')?.addEventListener('click',()=>void action(async()=>{await api.ready();await refresh();}));
 if(m?.result){const delay=Math.max(0,CONFIG.reveal_ms-(Date.now()-(revealStarts.get(m.id)??Date.now())));revealTimer=window.setTimeout(()=>{render(true);},delay+15);}updateTimers();
}
async function prepare(){
 const m=snapshot?.match;if(!m||m.status!=='briefing'||preparing)return;
 if(Date.now()-(briefingSeen.get(m.id)??Date.now())<CONFIG.briefing_min_ms)return;
 void effects.unlock();preparing=true;render(true);try{await api.prepare(m.id);await refresh();}catch(e){fail(e);}finally{preparing=false;render(true);}
}
async function choose(side:Side){const m=snapshot?.match;if(view!=='play'||!m||m.status!=='locked'||m.ownChoice||submitting||Date.now()+offset>=m.deadline)return;void effects.unlock();effects.choice();submitting=true;error='';render(true);try{await api.submit(m.id,side);announce(`Your ${side} choice is locked.`);await refresh();}catch(e){fail(e);await refresh();}finally{submitting=false;render(true);}}
function renderFeedback(m:MatchView){
 const me=snapshot!.me!,isKicker=m.kicker===me.id,win=isKicker?m.result!.goal:!m.result!.goal,index=Math.max(0,me.kicks+me.keeps-1),card=CARDS[index];
 const label=outcomeLabel(m.result!),detail=m.result!.goal?(isKicker?'You found the net.':'The striker found the net.'):(isKicker?'No goal this time.':m.result!.visualOutcome==='save'?'You made the save.':'No goal. A point for you.');
 shell(`${progressHeader(label)}<div class="matchup-line"><span>${mode==='practice'?'Practice matchup':'Human matchup'}</span><span>vs <strong>${esc(isKicker?m.keeperPlayer.username:m.kickerPlayer.username)}</strong></span></div><section class="feedback-layout"><div class="feedback-left"><div class="feedback-pitch"><canvas id="pitch" aria-label="${esc(outcomeDetail(m.result!))}. The penalty has resolved."></canvas><div class="result-meta"><span>Shot ${m.result!.kickerChoice.toUpperCase()} (${m.result!.kickerN?'N':'U'}) · Dive ${m.result!.keeperChoice.toUpperCase()}</span><span>Goal chance ${pct(m.result!.probability,2)}</span></div></div><div class="result-summary ${win?'win':'loss'}"><span>${win?'✓':'×'}</span><div><h3>${detail}</h3><p>${win?'One win':'One loss'} on your record. ${!m.result!.goal?'Saves and striker misses both count as goalkeeper wins.':'The goal came from the matrix probability, not a timing bonus.'}</p></div></div><button class="text-button" id="replay">Replay this penalty ↻</button></div><article class="result-card teaching-card ${win?'win':'loss'}" data-card="${card.id}"><div class="card-index"><span>GAME THEORY, BETWEEN PENALTIES</span><b>${String(index+1).padStart(2,'0')} / 12</b></div><h2>${esc(card.title)}</h2><p class="teaching-text">${esc(card.text)}</p><button class="btn ${win?'teal':'secondary'} wide" id="continue" disabled><span id="continue-copy">Take a moment to read…</span>${icon('arrow')}</button><p class="caption">Continue when you have finished reading. All twelve boxes are available under Game theory.</p></article></section>`);
 mountPitch({match:m,revealAt:0,win});$('#continue')!.addEventListener('click',()=>void action(async()=>{await api.ready();await refresh();window.scrollTo({top:0,behavior:'instant'});}));
 $('#replay')?.addEventListener('click',()=>{pitch?.set({match:m,revealAt:Date.now(),win});announce('Replaying the same result. No new draw.');});
 if(!seenSent.has(m.id)){seenSent.add(m.id);void api.seen(m.id).then(()=>refresh()).catch(e=>{seenSent.delete(m.id);fail(e);});}updateTimers();announce(`${outcomeDetail(m.result!)}. ${win?'You win.':'You lose.'} Game theory box ${index+1}: ${card.title}.`);
}
function renderFinal(){
 const me=snapshot!.me!,r=data?record(data,p=>p.id===me.id):null,finished=me.kicks+me.keeps===12;
 shell(`<section class="final"><div class="eyebrow">${finished?'Twelve penalties. Plenty to think about.':'The instructor has ended this room.'}</div><h1>${finished?'That’s full time,':'The whistle has gone,'}<br><em class="micro-text">${esc(me.username)}.</em></h1><p>${finished?'Six as striker. Six as goalkeeper. Now compare the class’s choices with predicted play.':'Your completed penalties are preserved. Incomplete appearances are not invented to balance the dataset.'}</p><div class="final-numbers"><div class="final-number"><b>${r?r.wins:'—'}<span class="muted">–${r?r.losses:'—'}</span></b><span>Actual wins–losses</span></div><div class="final-number"><b>${me.kicks}<span class="muted"> / 6</span></b><span>Kicks completed</span></div><div class="final-number"><b>${me.keeps}<span class="muted"> / 6</span></b><span>Keeps completed</span></div></div>${history()}<div class="panel"><span class="pill ${me.preference}">TEAM ${me.preference.toUpperCase()}</span><div class="spacer"></div><h2 style="font-size:30px">${data?teamLead(data):'The team contest is still taking shape.'}</h2><p class="caption" style="margin-top:15px">Your average win chance: <strong>${pct(r?.chance??null)}</strong>. Equal weight to striking and keeping; a description of encountered choices, not a measure of latent ability.</p></div><div class="spacer"></div><button class="btn teal" data-final-nav="statistics">Frequencies vs predicted play ${icon('arrow')}</button><button class="btn secondary" data-final-nav="notes">Revisit the twelve text boxes</button>${mode==='practice'?'<div><button class="text-button" id="reset-practice">Reset this isolated practice session</button></div>':''}</section>`);
 root.querySelectorAll<HTMLButtonElement>('[data-final-nav]').forEach(b=>b.onclick=()=>go(b.dataset.finalNav!));$('#reset-practice')?.addEventListener('click',()=>{api.close();clearPractice();location.hash='play';location.reload();});
}
function frequencyChart(s:Stream,show:boolean){
 const rate=s.n?s.s/s.n:null;return `<article class="frequency ${s.preference}"><div class="flex between"><div><h3>${s.role==='kicker'?'Strikers':'Goalkeepers'} · Team ${s.preference==='micro'?'Micro':'Macro'}</h3><span class="caption">${s.s}/${s.n} N choices · ${s.people} distinct ${s.people===1?'player':'players'}</span></div><span class="frequency-value">${pct(rate)}</span></div>${s.n?`<div class="prediction-comparison"><span>OBSERVED <strong>${pct(rate,2)}</strong></span>${show?`<span>PREDICTED <strong>${pct(s.benchmark,2)}</strong></span>`:''}</div><div class="chart" role="img" aria-label="Observed natural-side frequency ${pct(rate)}. Confidence sequence ${pct(s.band[0])} to ${pct(s.band[1])}, based on ${s.inferenceN} ordered observations."><i class="band" style="left:${s.band[0]*100}%;width:${(s.band[1]-s.band[0])*100}%"></i>${show?`<i class="reference" style="left:${s.benchmark*100}%"></i>`:''}<i class="dot" style="left:${rate!*100}%"></i></div><div class="chart-axis"><span>0%</span><span>50%</span><span>100%</span></div><div class="frequency-foot"><span>CS ${pct(s.band[0])}–${pct(s.band[1])} · n = ${s.inferenceN}</span>${show?`<span class="${s.excluded?'inference-frozen':''}">${s.excluded?'Benchmark outside the band':'Benchmark not excluded'}</span>`:''}</div>${s.blocked?`<p class="stream-note">${s.blocked==='cancelled'?'Missing-data stop: this inference stream is frozen.':'Waiting for an earlier assigned attempt to close.'} ${s.buffered} later resolved ${s.buffered===1?'observation is':'observations are'} descriptive only.</p>`:''}${show&&s.everExcluded?'<p class="caption tiny">The benchmark crossed the threshold at an earlier scheduled look.</p>':''}`:`<div class="empty" style="margin-top:18px;padding:20px">No resolved observations in this group.<br>${show?`Predicted N frequency: ${pct(s.benchmark,2)}.`:'An empty group is not a zero frequency.'}</div>`}</article>`;
}
function methodPanel(){return `<details class="method"><summary>Method · frequencies are not a complete test of equilibrium</summary><p>There are twelve prespecified streams: role × own declared preference, pooled over opponents (four), and role × own preference × opponent preference (eight). N is always relative to the striker. The exact four-cell matrix fixes the minimax benchmarks; they are not estimated from the class.</p><p>The band is a time-uniform Bernoulli beta-mixture confidence sequence. With S natural-side choices in n observations, invert log B(S+1,n−S+1) − S log p − (n−S) log(1−p) &lt; log(12/0.05). The familywise error budget is 0.05 across twelve prespecified streams and repeated looks. At n=0 the interval is [0,1]. These are not Bayesian credible intervals.</p><p>The guarantee assumes a common, constant conditional Bernoulli probability within each stream: at the benchmark, the specified fresh-randomization model. Arbitrary heterogeneous or coordinated choices do not satisfy that assumption automatically. A benchmark inside its band is not proof of equilibrium, and matching marginal frequencies do not establish independence or optimal responses.</p><p>Inference uses match-assignment order fixed before choices. Unresolved attempts buffer later results; a cancelled attempt freezes the affected inference prefix. All later valid penalties are still retained in descriptive frequencies and rankings. Timeouts are reported separately; no missing decisions are filled in.</p><p>A non-goal is a goalkeeper win whether the ball is saved, hits a post, goes wide or goes over. The animation does not alter the four matrix probabilities. Team preferences are self-selected, so team differences are descriptive, not causal.</p></details>`;}
function activeHostStats():Statistics|null{return hostApi&&hostData?.room.code===code?hostData:null;}
function renderStatistics(){
 const hostStats=activeHostStats(),roomStats=hostStats??(joined?data:null);
 if(!roomStats){shell(`<div class="page-head stats-question"><div class="eyebrow">Frequencies vs predicted play</div><h1>Are statistical frequencies distinct from predicted play?</h1><p>Join the game to see the room’s actual choices. No observations or scores are invented here.</p></div><button class="btn" id="back-play">Go to Play ${icon('arrow')}</button>`);$('#back-play')!.addEventListener('click',()=>go('play'));return;}
 const d=roomStats,t=teams(d),valid=d.matches.filter(m=>m.status==='resolved'),cancelled=d.matches.filter(m=>m.status==='cancelled').length,unresolved=d.matches.filter(m=>['briefing','locked'].includes(m.status)).length,ss=streams(d).filter(s=>opponentFilter==='all'?s.opponent===null:s.opponent===opponentFilter),rank=rankings(d),qualified=rank.filter(r=>r.chance!==null),qualifying=rank.filter(r=>r.chance===null);
 shell(`<div class="page-head stats-question"><div class="eyebrow">The question for the class</div><h1>Are statistical frequencies<br class="desktop-only"> distinct from predicted play?</h1><p>Compare natural-side choices with the minimax prediction. A numerical gap alone is not enough: look at the uncertainty band, the sample size and the assumptions.</p></div><div class="stat-counts"><span><i class="status-dot"></i><strong>${valid.length}</strong> resolved penalties</span><span>${d.players.length} players</span><span>${unresolved} in progress</span><span>${cancelled} cancelled</span></div><section class="stats-section primary-stats"><div class="section-heading"><div><h2>Observed choices. Predicted frequencies.</h2><p class="caption" style="margin-top:8px">N refers to the striker’s natural side for <em>both</em> roles. Percentages below are choices, not scoring probabilities.</p></div><select id="opponent-filter" aria-label="Opponent declared preference"><option value="all" ${opponentFilter==='all'?'selected':''}>All opponents</option><option value="micro" ${opponentFilter==='micro'?'selected':''}>Micro opponents</option><option value="macro" ${opponentFilter==='macro'?'selected':''}>Macro opponents</option></select></div><div class="chart-grid">${ss.map(s=>frequencyChart(s,d.room.showBenchmarks)).join('')}</div><div class="legend"><b>● Observed frequency</b>${d.room.showBenchmarks?`<b><i class="dash"></i>Predicted: strike ${pct(BENCHMARKS.kicker,2)} · keep ${pct(BENCHMARKS.keeper,2)}</b>`:''}<b><i></i>Time-uniform confidence sequence</b></div><div class="notice">${d.room.showBenchmarks?`${ss.filter(s=>s.excluded).length} of ${ss.length} displayed streams currently have their benchmark outside the band. <strong>“Not excluded” is not proof of equilibrium.</strong> `:''}${cancelled?'A cancellation has occurred: affected inference streams stop before that missing record; later observations remain descriptive.':'Only resolved, released choices enter these statistics. Unresolved records temporarily hold up their ordered inference streams.'}</div>${methodPanel()}</section>${hostStats?'':history()}<section class="stats-section"><div class="section-heading"><div><span class="eyebrow">The score is a different question</span><h2>Micro vs Macro.</h2><p class="caption" style="margin-top:8px">${teamLead(d)} Equal weight to striking and keeping, not the size of the team.</p></div></div><div class="stats-hero">${(['micro','macro'] as Side[]).map(side=>`<div class="team-stat ${side}"><div><span class="eyebrow" style="margin-bottom:12px">Average win chance</span><h2 class="${side}-text">Team ${side==='micro'?'Micro':'Macro'}</h2><p class="caption">${t[side].kick.n} kicks · ${t[side].keep.n} keeps</p></div><div><div class="team-big ${side}-text">${pct(t[side].chance)}</div><p class="caption">Actual balanced success: ${pct(t[side].actual)}</p></div></div>`).join('')}</div><p class="caption">Declared preferences are self-selected. This comparison does not measure the causal effect of studying Micro or Macro.</p></section><section class="stats-section"><div class="section-heading"><h2>Choices first. Then chance.</h2></div><div class="outcome-grid">${(['micro','macro'] as Side[]).flatMap(side=>(['kick','keep'] as const).map(role=>{const x=t[side][role];return `<div class="outcome"><span class="${side}-text">${side==='micro'?'Micro':'Macro'} ${role==='kick'?'strikers':'goalkeepers'}</span><b>${pct(x.actual)}</b><small>Actual ${role==='kick'?'goal':'stop'} rate · n = ${x.n}</small><small>Matrix-implied average: ${pct(x.expected)}</small></div>`;})).join('')}</div><p class="caption" style="margin-top:12px">A goalkeeper stop includes a save or a striker miss. The known scoring probabilities are not estimated confidence intervals.</p></section><section class="stats-section"><div class="section-heading"><div><h2>The player ranking.</h2><p class="caption" style="margin-top:8px">Top ten by average win chance — equal weight to striking and keeping.</p></div></div>${qualified.length?`<div class="table-wrap"><table class="ranking-table"><thead><tr><th>#</th><th>Username</th><th class="optional-col">Actual record</th><th>Win chance</th></tr></thead><tbody>${qualified.slice(0,10).map((r,i)=>`<tr><td class="rank-num">${i+1}</td><td><strong>${esc(r.player.username)}</strong><small class="${r.player.preference}-text">Team ${r.player.preference} · K ${r.kick.n}/6 · G ${r.keep.n}/6</small></td><td class="optional-col">${r.wins}–${r.losses}</td><td><strong>${pct(r.chance)}</strong><small>${r.complete?'6 + 6 completed':'Provisional'} · ${r.wins}W ${r.losses}L</small></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">A player needs one completed penalty in each role to receive a rank.</div>'}<p class="caption" style="margin-top:13px">${qualifying.length} still qualifying. Scores describe the choices and opponents encountered, not underlying ability. Ties: actual role-balanced success, then username and id. Early rankings are provisional.</p></section>`);
 $('#opponent-filter')!.addEventListener('change',e=>{opponentFilter=(e.target as HTMLSelectElement).value;render(true);});
}
function renderNotes(){shell(`<div class="page-head"><div class="eyebrow">Game theory, between penalties</div><h1>Twelve things to think about.</h1><p>The text boxes from your first game theory lecture. The same ideas, whatever the result on the pitch.</p></div>${joined?history():''}<div class="notes-grid">${CARDS.map((card,i)=>`<article class="note-card" id="${card.id}"><div class="card-index"><span>EC487 · GAME THEORY</span><b>${String(i+1).padStart(2,'0')} / 12</b></div><h2>${esc(card.title)}</h2><p>${esc(card.text)}</p></article>`).join('')}</div>`);}
function connectionState(state:string){connection=state;const el=$('#connection-state');if(el){el.dataset.state=state;el.title=state==='connected'?'Connected':state==='reconnecting'?'Connection interrupted. Recovering the same player…':'Connecting…';}$('#connection-dot')?.classList.toggle('reconnecting',state==='reconnecting');}
async function refresh(){
 if(!joined||document.hidden)return;if(busyRefresh){refreshAgain=true;return;}busyRefresh=true;
 try{const started=Date.now(),s=await api.snapshot();offset=s.serverNow-(started+Date.now())/2;snapshot=s;connectionState('connected');
  const needStats=view==='statistics'||s.me?.status==='finished'||s.room.phase==='ended';
  if((mode!=='supabase'||needStats)&&(!data||(s.room.version!==data.room.version&&(s.room.phase==='ended'||Date.now()-lastStatsAt>4500)))){
   try{data=await api.statistics();lastStatsAt=Date.now();}catch{/* Preserve the last authorized statistics; retry without replacing the player. */}
  }
  error='';render();connectionState('connected');if(s.room.phase==='ended'&&!s.me?.pendingResult&&data?.room.version===s.room.version){unsubscribe?.();unsubscribe=null;api.close();}
 }catch(e){connectionState('reconnecting');if(!snapshot)fail(e);}
 finally{busyRefresh=false;if(refreshAgain){refreshAgain=false;notificationTimer=window.setTimeout(()=>void refresh(),120);}}
}
function subscribe(){unsubscribe?.();unsubscribe=api.subscribe(()=>{if(document.hidden)return;clearTimeout(notificationTimer);notificationTimer=window.setTimeout(()=>void refresh(),90);});}
async function action(fn:()=>Promise<void>){try{error='';await fn();render(true);}catch(e){fail(e);}}
function updateTimers(){
 if(document.hidden||!snapshot?.me)return;const now=Date.now()+offset,me=snapshot.me,m=snapshot.match;
 if(m?.status==='briefing'){
  const prepared=m.kicker===me.id?m.kickerPrepared:m.keeperPrepared,b=$<HTMLButtonElement>('#prepare'),text=$('#prepare-copy'),remaining=Math.max(0,CONFIG.briefing_min_ms-(Date.now()-(briefingSeen.get(m.id)??Date.now())));
  if(b&&text){b.disabled=prepared||preparing||remaining>0;text.textContent=prepared?'Ready · waiting for the other player…':preparing?'Getting ready…':remaining?`Review your chances · ${Math.ceil(remaining/1000)}s`:'Ready — choose a side';}
 }else if(m?.status==='locked'){
  const left=Math.max(0,m.deadline-now),sec=Math.ceil(left/1000),el=$('#seconds');if(el)el.textContent=String(sec);const away=$('#away-clock');if(away)away.textContent=String(sec);$('#clock')?.classList.toggle('urgent',sec<=3);if(!m.ownChoice)effects.countdown(m.id,sec);$('#clock-arc')?.setAttribute('style',`stroke-dashoffset:${163.36*(1-left/CONFIG.decision_ms)}`);if(!left&&!m.ownChoice)root.querySelectorAll<HTMLButtonElement>('[data-choice]').forEach(b=>b.disabled=true);
 }else if(m?.result){if(view==='play'&&revealing(m))effects.reveal(m.id,Date.now()-(revealStarts.get(m.id)??Date.now()),m.result.visualOutcome,m.kicker===me.id?m.result.goal:!m.result.goal);const b=$<HTMLButtonElement>('#continue'),text=$('#continue-copy');if(b&&text){const ms=me.feedbackSince===null?CONFIG.feedback_ms:Math.max(0,CONFIG.feedback_ms-(now-me.feedbackSince));b.disabled=ms>0;text.textContent=ms>0?`A moment to read · ${Math.ceil(ms/1000)}s`:me.kicks+me.keeps>=12?'See my final results':'Continue to the next penalty';}}
}
function renderHost(){shell(`<div class="page-head"><div class="eyebrow">Instructor’s touchline</div><h1>Keep the class in play.</h1><p>A room code invites students. It never grants instructor access.</p></div>${mode==='practice'?`<div class="notice">This standalone preview is simulated. Run the local server for a two-human rehearsal, or configure Supabase for a classroom room.</div><div class="spacer"></div><button class="btn secondary" id="back-play">Return to practice</button>`:!hostData?`<form id="host-form" class="host-form panel"><h2 style="font-size:29px">Instructor sign-in</h2>${mode==='local'?'<label>Local instructor token<input id="host-token" type="password" autocomplete="off" placeholder="Printed by the local server" required></label>':'<label>Instructor email<input id="host-email" type="email" autocomplete="username" required></label><label>Password<input id="host-password" type="password" autocomplete="current-password" required></label>'}${mode==='supabase'?'<label>Room data mode<select id="host-practice"><option value="true">Test rehearsal — separate from teaching data</option><option value="false">Teaching room</option></select></label>':''}<label>Room code<input id="host-code" value="${esc(code)}" minlength="4" maxlength="8" required></label><div class="notice">${mode==='local'?'The local token is separate from the room code. It controls only this test server.':'The server must whitelist your real authenticated account as an instructor. Students cannot assign themselves this role.'}</div><div id="captcha"></div><div class="host-actions"><button class="btn" type="submit" name="operation" value="open">Open room controls</button><button class="btn secondary" type="submit" name="operation" value="create">Create a new room</button></div></form>`:hostDashboard()}`);$('#back-play')?.addEventListener('click',()=>go('play'));
 if($('#host-form'))mountCaptcha();
 $('#host-form')?.addEventListener('submit',async ev=>{ev.preventDefault();await action(async()=>{
  const requested=$<HTMLInputElement>('#host-code')!.value.trim().toUpperCase();
  hostApi?.close();hostApi=mode==='supabase'?new SupabaseTransport(requested,true):new LocalTransport(requested);
  if(hostApi instanceof LocalTransport)hostApi.hostToken=$<HTMLInputElement>('#host-token')!.value;
  if(hostApi instanceof SupabaseTransport)await hostApi.auth.password($<HTMLInputElement>('#host-email')!.value,$<HTMLInputElement>('#host-password')!.value);
  const op=(ev as SubmitEvent).submitter?.getAttribute('value');
  if(op==='create')await hostApi.host('create',mode==='local'||$<HTMLSelectElement>('#host-practice')?.value!=='false');
  const next=await hostApi.statistics();
  if(requested!==code){unsubscribe?.();unsubscribe=null;api.close();code=requested;api=transport(mode,code);snapshot=null;data=null;joined=false;loading=false;preference=null;}
  hostData=next;hostPreflight=mode==='supabase'?await hostApi.host('preflight') as Record<string,unknown>:null;
  putStore(`penalty:room:${mode}`,code);window.history.replaceState(null,'',`#host?room=${encodeURIComponent(code)}`);render(true);
 });});
 $('#switch-host-room')?.addEventListener('click',()=>{hostApi?.close();hostApi=null;hostData=null;hostPreflight=null;render(true);});
 root.querySelectorAll<HTMLButtonElement>('[data-host-action]').forEach(b=>b.onclick=()=>void action(async()=>{if(b.dataset.hostAction==='end'&&!confirm('End this session? Locked attempts will be cancelled, and no new matches will be made.'))return;const val=b.dataset.value==='true'?true:b.dataset.value==='false'?false:undefined;await hostApi!.host(b.dataset.hostAction!,val);hostData=await hostApi!.statistics();render(true);}));
 $('#check-backend')?.addEventListener('click',()=>void action(async()=>{hostPreflight=await hostApi!.host('preflight') as Record<string,unknown>;render(true);}));
 $('#export-csv')?.addEventListener('click',()=>void action(async()=>{download(await hostApi!.export(),`penalty-${code}-${new Date().toISOString().slice(0,10)}.csv`,'text/csv');}));$('#copy-join')?.addEventListener('click',()=>void navigator.clipboard.writeText(joinUrl()).then(()=>toast('Join link copied.')).catch(()=>toast(joinUrl())));
 if(hostData){const qr=$<HTMLCanvasElement>('#join-qr');if(qr)void renderQR(qr,joinUrl());}}
function joinUrl(){return location.href.split('#')[0]+`#play?room=${encodeURIComponent(code)}`;}
async function renderQR(canvas:HTMLCanvasElement,text:string){try{const {drawQR}=await import('./lib/qr.js');drawQR(canvas,text);}catch{canvas.hidden=true;}}
function hostDashboard(){const d=hostData!,r=d.room,counts=(status:string)=>d.players.filter(p=>p.status===status).length;return `<div class="host-grid"><div class="stack"><div class="panel"><div class="flex between"><h2 style="font-size:30px">${esc(code)}</h2><span class="pill cream">${esc(r.phase)} · ${r.practice?'TEST ROOM':'TEACHING ROOM'}</span></div><div class="divider"></div><div class="host-actions">${r.phase==='lobby'?'<button class="btn teal" data-host-action="start">Start play</button>':''}${r.phase==='playing'?'<button class="btn secondary" data-host-action="pause">Pause new matching</button>':''}${r.phase==='paused'?'<button class="btn teal" data-host-action="resume">Resume matching</button>':''}${r.phase!=='ended'?`<button class="btn secondary" data-host-action="entry" data-value="${!r.entryOpen}">${r.entryOpen?'Close':'Open'} entry</button><button class="btn secondary" data-host-action="benchmarks" data-value="${!r.showBenchmarks}">${r.showBenchmarks?'Hide':'Show'} benchmarks</button><button class="btn danger" data-host-action="end">End session</button>`:''}</div><p class="caption" style="margin-top:20px">Closing entry does not end existing games. Pausing stops new pairings, not the twelve-second clocks of already locked matches.</p></div><div class="host-counts">${[['waiting','Waiting'],['matched','In a match'],['finished','Finished'],['away','Timed out'],['feedback','Reading'],['lobby','In the lobby']].map(([s,l])=>`<div><b>${counts(s)}</b><span>${l}</span></div>`).join('')}</div><div class="notice">${d.counts?.connected??'—'} connected · ${d.counts?.disconnected??'—'} disconnected · ${d.matches.filter(m=>m.status==='cancelled').length} cancelled attempts · ${d.matches.filter(m=>m.status==='resolved').length} valid penalties. Disconnected waiting clients leave the eligible pool after 25 seconds; detailed disconnection diagnostics require the database export.</div><div class="host-actions"><button class="btn secondary" id="export-csv">Export auditable CSV</button><button class="btn secondary" id="switch-host-room">Open or create another room</button></div>${mode==='supabase'?`<div class="panel preflight-result"><div class="flex between"><b>Backend check</b><button id="check-backend" class="btn secondary small">Check backend</button></div><p>${hostPreflight?`API v${esc(hostPreflight.apiVersion)} · Database ${esc(hostPreflight.databaseVersion)}<br>Server clock: <strong>${hostPreflight.clockHealthy?'running ✓':'NOT RUNNING — enable the Cron job'}</strong> · last tick ${hostPreflight.clockAgeMs===null?'not recorded':`${Math.max(0,Number(hostPreflight.clockAgeMs)/1000).toFixed(1)}s ago`} at check time.`:'Run a check before starting the classroom.'}</p><p class="caption">This tests the backend and clock, not your sign-in quota or campus Wi-Fi. Rehearse those before class.</p></div>`:''}</div><div class="stack"><div class="host-join"><span class="eyebrow">Student join code</span><b>${esc(code)}</b><p class="caption">${esc(joinUrl())}</p><div class="spacer"></div><div class="flex wrap"><canvas id="join-qr" class="qr" aria-label="QR code for the actual join link shown above"></canvas><button class="btn secondary small" id="copy-join">Copy join link</button></div></div><div class="notice warning"><strong>Before a classroom deployment:</strong> check anonymous-sign-in limits for your shared campus IP; rehearse on the actual Wi-Fi and students’ devices. Use a test room for the rehearsal, then a new teaching room so test choices are not pooled with the class.</div></div></div>`;}
function download(text:string,name:string,mime:string){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:mime}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000);}
window.addEventListener('hashchange',()=>{view=location.hash.slice(1).split('?')[0]||'play';const requested=hashParams().get('room')?.toUpperCase();if(mode!=='practice'&&requested&&requested!==code){unsubscribe?.();api.close();code=requested;if(hostData?.room.code!==code){hostApi?.close();hostApi=null;hostData=null;hostPreflight=null;}api=transport(mode,code);snapshot=null;data=null;joined=false;preference=null;error='';void start();}else render(true);window.scrollTo({top:0});if(view==='statistics'){lastStatsAt=0;void refresh();}});
window.addEventListener('keydown',event=>{if(event.altKey||event.ctrlKey||event.metaKey||event.repeat)return;const target=event.target as HTMLElement;if(['INPUT','TEXTAREA','SELECT'].includes(target.tagName)||target.isContentEditable)return;if((event.key==='ArrowLeft'||event.key==='1')&&view==='play'&&snapshot?.match?.status==='locked'){event.preventDefault();void choose('micro');}if((event.key==='ArrowRight'||event.key==='2')&&view==='play'&&snapshot?.match?.status==='locked'){event.preventDefault();void choose('macro');}});
setInterval(updateTimers,100);
setInterval(()=>{
 if(document.hidden)return;
 if(joined&&!(snapshot?.room.phase==='ended'&&!snapshot?.me?.pendingResult&&data?.room.version===snapshot.room.version)){
  if(Date.now()-lastHeartbeat>8000){lastHeartbeat=Date.now();void api.heartbeat().catch(()=>connectionState('reconnecting'));}
  // Realtime drives normal play. This resync remains available if Wi-Fi drops it.
  void refresh();
 }
 if((view==='host'||view==='statistics')&&hostApi&&activeHostStats()&&hostData?.room.phase!=='ended'&&!hostRefreshing){hostRefreshing=true;void hostApi.statistics().then(d=>{hostData=d;render();}).catch(fail).finally(()=>hostRefreshing=false);}
},3000+Math.floor(Math.random()*400));
document.addEventListener('visibilitychange',()=>{if(document.hidden){effects.quiet();}else if(joined&&snapshot?.room.phase!=='ended'){subscribe();void api.heartbeat().then(()=>refresh()).catch(fail);}});
window.addEventListener('online',()=>{if(joined&&snapshot?.room.phase!=='ended')subscribe();void refresh();});
window.addEventListener('offline',()=>connectionState('reconnecting'));
window.addEventListener('pageshow',event=>{if(event.persisted&&joined){subscribe();void refresh();}});
window.addEventListener('pagehide',()=>{effects.quiet();unsubscribe?.();api.close();hostApi?.close();pitch?.destroy();});
async function start(){if(mode==='supabase'&&(!config.supabaseUrl||!config.supabaseKey)){api.close();shell('<section class="page-head"><div class="eyebrow">Deployment setup</div><h1>Connect your classroom.</h1><p>This is the live build, but its Supabase project URL and publishable key have not been configured. Add the two GitHub repository variables described in START-HERE.md, then rerun the Pages workflow. No simulated opponents will be introduced into a live room.</p></section>');return;}render(true);const remembered=mode==='practice'?getStore('penalty:practice:v1'):getStore(`penalty:joined:${mode}:${code}`);if(remembered&&view!=='host'){loading=true;render(true);try{snapshot=await api.snapshot();joined=!!snapshot.me;offset=snapshot.serverNow-Date.now();if(joined){subscribe();await api.heartbeat();await refresh();}}catch{/* A failed fetch never creates a new identity. */}finally{loading=false;render(true);}}}
void start();
